import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"链路状态","description":"","frontmatter":{"title":"链路状态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/link-state.md","filePath":"cs/link-state.md","lastUpdated":1789023840000}'),h={name:"cs/link-state.md"};function _(S,a,P,E,A,m){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="链路状态" tabindex="-1">链路状态 <a class="header-anchor" href="#链路状态" aria-label="Permalink to &quot;链路状态&quot;">​</a></h1><div class="epigraph"><p>每台路由器描述自己的邻接，洪泛全网；每台用同一张图跑最短路，得到下一跳。</p><footer>—— 据 Dijkstra 最短路；Moy, RFC 2328 OSPF Version 2 整理</footer></div><p><a href="/cs/count-to-infinity">上一课</a>只交换摘要距离，坏消息慢。缺口是<strong>链路状态</strong>：通告「我连着谁、代价多少」，各节点独立计算。图课的 <a href="/cs/dijkstra">Dijkstra</a> 已会单源最短路；本课把它接到 OSPF 式的洪泛与区域直觉，不把 LSA 类型表背完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DV 看不到边，无法可靠地区分「真断」与「邻居还在用我」。链路状态：邻接建立后，产生本节点的状态，可靠洪泛（确认、序号），每节点得同一有向图（理想情况），再 Dijkstra 出转发表。缺口不是 LPM 规则，而是这套「复制图 + 本地计算」。</p><p>本课不把 IS-IS TLV 与 OSPF 逐字段对照。</p><p><span class="marginnote">洪泛要可靠且防环：序号与老化。分区用区域把图缩小，边界仍摘要，这是规模，不是另一算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Hello 发现邻居；邻接同步数据库；边变化则新版本 LSA 洪泛；SPF 计算：对每个前缀取最短路径的第一跳，写入 <a href="/cs/lpm">LPM</a>。代价通常是管理配置的正数，不是时延测量本身。与生成树不同：链路状态允许用所有边转发（按前缀下一跳），不必阻塞成树。</p>',9)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LSA%5B%22%E6%8F%8F%E8%BF%B0%E9%82%BB%E6%8E%A5%E7%9A%84%20LSA%22%5D%20--%3E%20FL%5B%22%E5%8F%AF%E9%9D%A0%E6%B4%AA%E6%B3%9B%22%5D%0A%20%20FL%20--%3E%20G%5B%22%E5%90%84%E8%8A%82%E7%82%B9%E5%90%8C%E4%B8%80%E5%9B%BE%22%5D%0A%20%20G%20--%3E%20SPF%5B%22Dijkstra%22%5D%0A%20%20SPF%20--%3E%20FIB%5B%22%E8%BD%AC%E5%8F%91%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收敛：坏边的 LSA 一到，所有人重算，不再靠互相引用旧距离。代价是内存与洪泛带宽、SPF 的 CPU。端到端仍不保证：SPF 期间可暂环，TTL 兜底。与 DV 对照：信息是边不是距离，计算在本地而不是嵌在通告里。</p><p>域内用 LS 或改进的 DV；域间政策不能用纯最短路——下一课 BGP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入流量工程扩展（RSVP-TE）当主干必学。不把 OSPF 与 BGP 的行政距离写成厂商手册。多区域摘要会导致区域内次优，点名即可。地址族 v4/v6 共用同一思想。</p><p>分区计算：区域内 SPF，区域间走摘要。摘要错误会造成黑洞，这是配置问题不是 Dijkstra 失败。</p><p>后课默认：域内可以有一张共享图。自治系统之间按政策选路，下一课 BGP 直觉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链路状态：洪泛邻接，本地 Dijkstra，填 LPM。</li><li>比 DV 看见边，收敛通常更快。</li><li>跨 AS 的政策不是最短路，下一课。</li><li>出处：Dijkstra；RFC 2328；Kurose and Ross。</li></ul>',9))])}const f=s(h,[["render",_]]);export{B as __pageData,f as default};
